async function run() {
  const repos = params.repositorios.split(/[,\s]+/)
    .map(function (r) { return r.trim().replace(/^https?:\/\/github\.com\//, "").replace(/\/+$/, ""); })
    .filter(function (r) { return /^[\w.-]+\/[\w.-]+$/.test(r); });
  const vistos = state.get("vistos") || {};
  const novidades = [];
  const agora = {};

  for (const repo of repos) {
    const items = await rss.read({url: "https://github.com/" + repo + "/releases.atom", max: 10});
    const links = items.map(function (i) { return i.link; }).filter(Boolean);
    const antes = vistos[repo];
    if (antes) {
      for (const item of items) {
        if (item.link && antes.indexOf(item.link) < 0) novidades.push({repo: repo, titulo: item.title || item.link, link: item.link});
      }
    } else {
      log("Primeira leitura de " + repo + ": " + links.length + " versões aprendidas.");
    }
    agora[repo] = (antes || []).filter(function (l) { return links.indexOf(l) < 0; }).concat(links).slice(-20);
  }

  state.set("vistos", agora);
  if (novidades.length === 0) {
    log("Nenhuma versão nova.");
    return;
  }
  const linhas = novidades.map(function (n) { return "• " + n.repo + " " + n.titulo + " — " + n.link; });
  await notify.send({text: "🚀 " + (novidades.length === 1 ? "Versão nova" : "Versões novas") + " no GitHub:\n" + linhas.join("\n")});
}
